// Validation des paramètres
const input = $input.first().json;
const body = input.body || input;

const textName = body.text_name || '';
const chapter = body.chapter || null;
const commentator = body.commentator || null;
const targetLanguage = body.target_language || 'fr';
const apiKey = body.api_key || '';
const openaiApiKey = body.openai_api_key || '';

// Validation
const errors = [];
if (!textName) errors.push('Le champ "text_name" est requis');
if (chapter === null) errors.push('Le champ "chapter" est requis');
if (!apiKey) errors.push('Le champ "api_key" (Anthropic) est requis');

// Générer un job_id unique
const jobId = 'job_' + Date.now().toString(36) + Math.random().toString(36).substring(2, 8);

// Encoder le nom du livre pour l'URL
const encodedTextName = encodeURIComponent(textName);

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    jobId: jobId,
    textName: textName,
    encodedTextName: encodedTextName,
    chapter: chapter,
    commentator: commentator,
    targetLanguage: targetLanguage,
    apiKey: apiKey,
    openaiApiKey: openaiApiKey
  }
}];

// Extraire les commentaires
const input = $input.first().json;
const prevData = $('Validate Input').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

// Vérifier les erreurs
if (statusCode >= 400 || data.error) {
  return [{
    json: {
      success: false,
      error: {
        code: statusCode,
        message: data.error?.message || data.message || data.detail || 'Commentaires non trouvés',
        status: 'COMMENTARIES_NOT_FOUND'
      }
    }
  }];
}

const commentaries = data.commentaries || [];

if (commentaries.length === 0) {
  return [{
    json: {
      success: false,
      error: {
        code: 404,
        message: `Aucun commentaire trouvé pour ${prevData.textName} chapitre ${prevData.chapter}` + (prevData.commentator ? ` (${prevData.commentator})` : ''),
        status: 'NO_COMMENTARIES'
      }
    }
  }];
}

// Filtrer les commentaires non traduits
const untranslated = commentaries.filter(c => !c.has_translation && !c.translation);

if (untranslated.length === 0) {
  return [{
    json: {
      success: true,
      alreadyComplete: true,
      message: 'Tous les commentaires sont déjà traduits',
      textName: prevData.textName,
      chapter: prevData.chapter,
      commentator: prevData.commentator,
      commentariesCount: commentaries.length,
      toTranslate: 0
    }
  }];
}

// Estimation du temps (~6 secondes par commentaire)
const estimatedSeconds = Math.ceil(untranslated.length * 6);

return [{
  json: {
    success: true,
    alreadyComplete: false,
    jobId: prevData.jobId,
    textName: prevData.textName,
    chapter: prevData.chapter,
    commentator: prevData.commentator,
    targetLanguage: prevData.targetLanguage,
    apiKey: prevData.apiKey,
    openaiApiKey: prevData.openaiApiKey,
    commentaries: untranslated,
    commentariesCount: commentaries.length,
    toTranslate: untranslated.length,
    estimatedSeconds: estimatedSeconds
  }
}];

// Extraire le job_id de la réponse API
const input = $input.first().json;
const prevData = $('Extract Commentaries').first().json;

const data = input.body || input;
const statusCode = input.statusCode || 200;

let jobId = prevData.jobId;
if (statusCode < 400 && data.job_id) {
  jobId = data.job_id;
}

return [{
  json: {
    ...prevData,
    jobId: jobId,
    jobCreated: statusCode < 400
  }
}];

// Préparer le payload pour le worker
const data = $input.first().json;

return [{
  json: {
    workerPayload: {
      job_id: data.jobId,
      text_name: data.textName,
      chapter: data.chapter,
      commentator: data.commentator,
      target_language: data.targetLanguage,
      api_key: data.apiKey,
      openai_api_key: data.openaiApiKey,
      commentaries: data.commentaries
    },
    jobId: data.jobId,
    textName: data.textName,
    chapter: data.chapter,
    commentator: data.commentator,
    commentariesCount: data.commentariesCount,
    toTranslate: data.toTranslate,
    estimatedSeconds: data.estimatedSeconds
  }
}];

// Préparer la réponse immédiate
const input = $('Prepare Worker Payload').first().json;

return [{
  json: {
    success: true,
    job_id: input.jobId,
    status: 'started',
    text_name: input.textName,
    chapter: input.chapter,
    commentator: input.commentator || 'all',
    commentaries_count: input.commentariesCount,
    to_translate: input.toTranslate,
    estimated_seconds: input.estimatedSeconds
  }
}];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];
